CREATE TABLE IF NOT EXISTS institutional_data_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution_id uuid NOT NULL REFERENCES institutional_profiles(id) ON DELETE CASCADE, project_id uuid REFERENCES projects(id) ON DELETE CASCADE, asset_id uuid REFERENCES assets(id) ON DELETE CASCADE, request_type text NOT NULL, purpose text, requested_fields jsonb NOT NULL DEFAULT '[]'::jsonb, status text NOT NULL DEFAULT 'submitted', reviewer text, response_notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());